import java.util.*;

public class Main {
    public static void main(String[] args) {
        // 1. Fully mutable list initialization
        List<String> roster = new ArrayList<>(Arrays.asList(
            "emp_david", "contractor_bob", "emp_alice", "contractor_eve", "emp_carol"
        ));
        System.out.println("Raw Roster: " + roster);

        // 2. In-Place Filtering: Drop all temporary contractors
        roster.removeIf(name -> name.startsWith("contractor_"));
        System.out.println("Employees Only: " + roster);

        // 3. In-Place Transformation: Strip prefix and capitalize
        roster.replaceAll(name -> name.replace("emp_", "").toUpperCase());
        System.out.println("Cleaned Names: " + roster);

        // 4. Natural Sorting
        Collections.sort(roster);
        System.out.println("Alphabetical: " + roster);

        // 5. Safe Sublist Extraction
        List<String> topTwo = new ArrayList<>(roster.subList(0, 2));
        System.out.println("Top 2 Leaders: " + topTwo);
    }
}

